var catalog=UnityEditor.AssetDatabase.LoadAssetAtPath<Jcc.Presentation.ReplayAssetCatalog>("Assets/Res/Replay/ReplayAssets.asset");
var list=new System.Collections.Generic.List<Jcc.Presentation.ReplayAssetCatalog.Entry>(catalog.entries);
if(!list.Exists(x=>x.key=="item/mittens")){var sprite=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>("Assets/Res/GUI/Image/Equipment/mittens.png");if(!sprite)throw new System.Exception("Missing item/mittens");list.Add(new Jcc.Presentation.ReplayAssetCatalog.Entry{key="item/mittens",sprite=sprite});}
