if(!list.Exists(x=>x.key=="item/forbidden_idol")){var sprite=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>("Assets/Res/GUI/Image/Equipment/forbidden_idol.png");if(!sprite)throw new System.Exception("Missing item/forbidden_idol");list.Add(new Jcc.Presentation.ReplayAssetCatalog.Entry{key="item/forbidden_idol",sprite=sprite});}
if(!list.Exists(x=>x.key=="augment/thegoldendragon2")){var sprite=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>("Assets/Res/GUI/Image/Augment/thegoldendragon2.png");if(!sprite)throw new System.Exception("Missing augment/thegoldendragon2");list.Add(new Jcc.Presentation.ReplayAssetCatalog.Entry{key="augment/thegoldendragon2",sprite=sprite});}
if(!list.Exists(x=>x.key=="cover/frontline-two-v1")){var sprite=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>("Assets/Res/GUI/Image/Cover/frontline-two-v1.png");if(!sprite)throw new System.Exception("Missing cover/frontline-two-v1");list.Add(new Jcc.Presentation.ReplayAssetCatalog.Entry{key="cover/frontline-two-v1",sprite=sprite});}
catalog.entries=list.ToArray();UnityEditor.EditorUtility.SetDirty(catalog);UnityEditor.AssetDatabase.SaveAssets();return "Episode 2 assets registered";